import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.BM5YPQmL.js";const c=JSON.parse('{"title":"درس العقارات","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/tutorials/real-estate.md","filePath":"ar/guide/tutorials/real-estate.md"}'),l={name:"ar/guide/tutorials/real-estate.md"};function r(n,a,h,o,p,d){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="درس-العقارات" tabindex="-1">درس العقارات <a class="header-anchor" href="#درس-العقارات" aria-label="Permalink to &quot;درس العقارات&quot;">​</a></h1><p>في هذا الدرس تصنع فيديو موضوعه: جولة قصيرة في شقة لوكالة عقارية خيالية. ستستخدم الحزمة <code>real-estate</code> وثيمها <code>estate</code>، ويستغرق العمل نحو عشر دقائق قبل التسجيل.</p><h2 id="_1-أنشئ-الحلقة" tabindex="-1">1. أنشئ الحلقة <a class="header-anchor" href="#_1-أنشئ-الحلقة" aria-label="Permalink to &quot;1. أنشئ الحلقة&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apartment-tour</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> real-estate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> property-tour</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ar</span></span></code></pre></div><p>استخدم <code>--lang en</code> لنسخة إنجليزية. وتضم الحزمة أيضاً القالبين <code>neighborhood-guide</code> و<code>buying-steps</code>. يعرض <a href="./../../reference/packs.html#real-estate">فهرس الحزم</a> كل القوالب وحقولها.</p><h2 id="_2-أدخل-بياناتك" tabindex="-1">2. أدخل بياناتك <a class="header-anchor" href="#_2-أدخل-بياناتك" aria-label="Permalink to &quot;2. أدخل بياناتك&quot;">​</a></h2><p>افتح الحلقة بالأمر <code>reelforge edit apartment-tour</code> واستبدل الأسماء والأرقام والكلمة المفتاحية الافتراضية ببياناتك، أو ابدأ من لوحة التحكم (<strong>+ New episode</strong> ثم <strong>Start from template</strong>)، فيطلب النموذج كل حقل على حدة. التزم بحدود الطول الظاهرة لكل حقل.</p><p><strong>الجمهور والنبرة.</strong> المشترون لأول مرة والمستأجرون والبائعون. كن واثقاً وعملياً من دون مبالغة.</p><ul><li>ضع في الافتتاحية المعلومة التي يسأل عنها المشتري أولاً (المساحة أو عدد الغرف أو السعر).</li><li>استخدم صورك الخاصة من مجلد <code>assets/</code> في الحلقة، ولا تستخدم صوراً لا تملكها.</li><li>اختم بخطوة واحدة واضحة، مثل حجز موعد للزيارة.</li></ul><h2 id="_3-راجع-المحتوى" tabindex="-1">3. راجع المحتوى <a class="header-anchor" href="#_3-راجع-المحتوى" aria-label="Permalink to &quot;3. راجع المحتوى&quot;">​</a></h2><ul><li>لا وعود بارتفاع القيمة أو بعائد إيجاري أو بأرباح «مضمونة».</li><li>الأسعار والرسوم كما يقدمها العميل فقط، وكل ما عداها يُوسَم بأنه «مثال».</li><li>صِف العقار والمنطقة، ولا تحدد لمن يناسب العقار بحسب الحالة العائلية أو الأصل أو الدين أو الإعاقة.</li></ul><h2 id="_4-تحقق-وسجّل-وصدّر" tabindex="-1">4. تحقق وسجّل وصدّر <a class="header-anchor" href="#_4-تحقق-وسجّل-وصدّر" aria-label="Permalink to &quot;4. تحقق وسجّل وصدّر&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apartment-tour</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apartment-tour</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # after you save voice.wav in the episode folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> render</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apartment-tour</span></span></code></pre></div><p>يوجد مثال مكتمل في <code>packs/real-estate/examples/maple-court-ar</code>؛ صدّره مع الخيار <code>--silent</code> للمقارنة.</p>`,14)])])}const g=e(l,[["render",r]]);export{c as __pageData,g as default};
